/**
 * Load Dashboard content
 */
async function loadDashboard() {
    console.log('Loading Dashboard...');

    // D2.3 — Show first-run prereqs banner if no prereq check has ever passed.
    // Presence of 'prereqs-verified-at' in localStorage = the operator has run
    // at least one check (any of System Deps, AWS Credentials, AWS Permissions,
    // SSH Key, GitHub CLI). Banner is informational only — doesn't gate deploy.
    try {
        const prereqsVerified = localStorage.getItem('prereqs-verified-at');
        const banner = document.getElementById('prereqs-first-run-banner');
        if (banner) {
            banner.style.display = prereqsVerified ? 'none' : 'block';
        }
    } catch (e) { /* ignore localStorage errors (privacy mode, etc.) */ }

    const statusDiv = document.getElementById('dashboard-status');
    if (!statusDiv) return;

    statusDiv.innerHTML = '<div class="spinner"></div>Loading dashboard...';
    
    try {
        statusDiv.innerHTML = `
            <div class="status-display info">
                <p><strong>Welcome to Red Team Infrastructure Manager</strong></p>
                <p>Use the Configuration tab to set up your infrastructure, then deploy from the Deploy tab.</p>
                <p style="margin-top: 10px;"><strong>Quick Start:</strong></p>
                <ul style="margin-left: 20px;">
                    <li>Verify AWS credentials and permissions in Pre Reqs tab</li>
                    <li>Set up your infrastructure parameters in Configuration</li>
                    <li>Upload Cobalt Strike and deploy from the Deploy tab</li>
                </ul>
            </div>
        `;
    } catch (error) {
        statusDiv.innerHTML = '<p>Error loading dashboard: ' + error.message + '</p>';
    }

    // Populate Elastic Rules card from the loaded JS data
    refreshElasticRulesCard();
}

function refreshElasticRulesCard() {
    const countEl = document.getElementById('elastic-rules-count');
    const dateEl = document.getElementById('elastic-rules-date');
    if (!countEl || !dateEl) return;
    if (typeof ELASTIC_RULES !== 'undefined' && ELASTIC_RULES.meta) {
        countEl.textContent = ELASTIC_RULES.meta.total_rules_mapped + ' rules mapped';
        dateEl.textContent = 'Last updated: ' + ELASTIC_RULES.meta.last_updated;
    }
}

async function updateElasticRules() {
    const btn = document.getElementById('btn-update-elastic-rules');
    const statusEl = document.getElementById('elastic-rules-status');
    if (btn) btn.disabled = true;
    if (statusEl) statusEl.textContent = 'Pulling latest rules...';

    try {
        const resp = await fetch('/api/config/update-elastic-rules', { method: 'POST' });
        const data = await resp.json();

        if (!data.success) {
            if (statusEl) statusEl.innerHTML = `<span style="color: var(--danger-text);">${data.error || 'Update failed'}</span>`;
            return;
        }

        // Reload elastic-rules.js by appending a cache-busted script tag
        const oldScript = document.querySelector('script[src*="elastic-rules"]');
        if (oldScript) oldScript.remove();
        const s = document.createElement('script');
        s.src = '/js/elastic-rules.js?t=' + Date.now();
        s.onload = function() {
            refreshElasticRulesCard();
            if (statusEl) statusEl.innerHTML = `<span style="color: var(--success-text);">Updated successfully</span>`;
        };
        document.head.appendChild(s);
    } catch (e) {
        if (statusEl) statusEl.innerHTML = `<span style="color: var(--danger-text);">Error: ${e.message}</span>`;
    } finally {
        if (btn) btn.disabled = false;
    }
}

/**
 * Load Configuration
 */
// Cache of Route 53 domains to avoid redundant API calls
let _route53DomainsCache = null;

async function loadRoute53Domains(selectedDomain = null, selectedBackups = []) {
    const select = document.getElementById('primary-domain');
    if (!select) return;

    // Preserve current selection if no override
    const currentVal = selectedDomain || select.value;

    // Show loading state
    select.innerHTML = '<option value="">Loading domains from Route 53...</option>';
    select.disabled = true;

    try {
        let data = _route53DomainsCache;
        if (!data) {
            const response = await fetch(`${API_BASE}/health/route53-domains`);
            data = await response.json();
            if (data.success) _route53DomainsCache = data;
        }

        select.innerHTML = '<option value="">-- Select a domain --</option>';

        if (data.success && data.domains.length > 0) {
            data.domains.forEach(d => {
                const opt = document.createElement('option');
                opt.value = d.domain_name;
                opt.textContent = d.domain_name;
                select.appendChild(opt);
            });
        } else if (data.success && data.domains.length === 0) {
            select.innerHTML = '<option value="">No domains found in Route 53</option>';
        } else {
            select.innerHTML = `<option value="">Error: ${data.error || 'Failed to load'}</option>`;
        }

        // Restore selection
        if (currentVal) {
            select.value = currentVal;
            if (select.value !== currentVal && currentVal !== '') {
                const opt = document.createElement('option');
                opt.value = currentVal;
                opt.textContent = `${currentVal} (not in Route 53)`;
                select.appendChild(opt);
                select.value = currentVal;
            }
        }

        // Update backup domains dropdown (excludes selected primary)
        updateBackupDomains(data, selectedBackups);

        // Re-update backups when primary changes
        select.onchange = () => updateBackupDomains(data);
    } catch (error) {
        select.innerHTML = `<option value="">Error loading domains</option>`;
        console.error('Failed to load Route 53 domains:', error);
    } finally {
        select.disabled = false;
    }
}

function updateBackupDomains(data, selectedBackups = []) {
    const backupSelect = document.getElementById('backup-domains');
    const primarySelect = document.getElementById('primary-domain');
    if (!backupSelect || !data || !data.success) return;

    const primaryVal = primarySelect ? primarySelect.value : '';

    // Preserve current selections if no override provided
    if (selectedBackups.length === 0) {
        selectedBackups = Array.from(backupSelect.selectedOptions).map(o => o.value);
    }

    backupSelect.innerHTML = '';

    const available = data.domains.filter(d => d.domain_name !== primaryVal);
    if (available.length === 0) {
        const opt = document.createElement('option');
        opt.value = '';
        opt.textContent = 'No additional domains available';
        opt.disabled = true;
        backupSelect.appendChild(opt);
        return;
    }

    available.forEach(d => {
        const opt = document.createElement('option');
        opt.value = d.domain_name;
        opt.textContent = d.domain_name;
        opt.selected = selectedBackups.includes(d.domain_name);
        backupSelect.appendChild(opt);
    });
}

